  line-height: 18px;
  color: var(--tlc-text-secondary);
}

.tlc__legend-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.tlc__legend-key {
  width: 16px;
  height: 2px;
  border-radius: 1px;
}

.tlc__svg {
  display: block;
  overflow: visible;
  outline: none;
  touch-action: none;
}

.tlc__svg:focus-visible {
  box-shadow: 0 0 0 2px var(--g-color-line-focus);
  border-radius: 4px;
}

.tlc__grid {
  stroke: var(--tlc-grid);
  stroke-width: 1;
  shape-rendering: crispEdges;
}

.tlc__axis {
  stroke: var(--tlc-axis);
  stroke-width: 1;
  shape-rendering: crispEdges;
}

.tlc__tick {
  font-size: 12px;
  fill: var(--tlc-text-secondary);
  font-variant-numeric: tabular-nums;
}

.tlc__line {
  fill: none;
  stroke-width: 2;
  stroke-linejoin: round;
  stroke-linecap: round;
}

.tlc__dot {
  stroke: var(--tlc-surface);
  stroke-width: 2;
}

.tlc__end-label {
  font-size: 12px;
  font-weight: 500;
  fill: var(--tlc-text-primary);
}

.tlc__leader {
  stroke: var(--tlc-axis);
  stroke-width: 1;
}

.tlc__crosshair {
  stroke: var(--tlc-crosshair);
  stroke-width: 1;
  shape-rendering: crispEdges;
  pointer-events: none;
}

.tlc__hit {
  fill: transparent;
  cursor: crosshair;
}

.tlc__tooltip {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 1;
  min-width: 140px;
  padding: 8px 12px;
  border-radius: 8px;
  background: var(--tlc-tooltip-bg);
  box-shadow:
    0 0 0 1px var(--tlc-grid),
    0 4px 12px var(--tlc-tooltip-shadow);
  font-size: 13px;
  line-height: 18px;
  pointer-events: none;
}

.tlc__tooltip-title {
  margin-bottom: 4px;
  color: var(--tlc-text-secondary);
}

.tlc__tooltip-row {
  display: grid;
  grid-template-columns: 12px auto 1fr;
  align-items: center;
  gap: 8px;
}

.tlc__tooltip-key {
  width: 12px;
  height: 2px;
  border-radius: 1px;
}

.tlc__tooltip-value {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--tlc-text-primary);
}

.tlc__tooltip-name {
  color: var(--tlc-text-secondary);
}

.tlc__table-value {
  font-variant-numeric: tabular-nums;
}

.tlc__sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
EOF
