      ),
      align: 'end' as const,
      template: (row: Row) => <span className="tlc__table-value">{formatValue(row[s.id] as number)}</span>,
    })),
  ];

  return (
    <div className="tlc">
      <Table data={rows} columns={columns} width="max" />
    </div>
  );
}
